    }

    if s.starts_with("0x") {
        return u64::from_str_radix(&s[2..], 16).map_err(|_| format!("Invalid hex: {}", s));
    }

    let (num_str, suffix) = if s.ends_with("kib") {
        (&s[..s.len()-3], 1024u64)
    } else if s.ends_with("mib") {
        (&s[..s.len()-3], 1024 * 1024)
    } else if s.ends_with("gib") {
        (&s[..s.len()-3], 1024 * 1024 * 1024)
    } else if s.ends_with("kb") {
        (&s[..s.len()-2], 1000u64)
    } else if s.ends_with("mb") {
        (&s[..s.len()-2], 1000 * 1000)
    } else if s.ends_with("gb") {
        (&s[..s.len()-2], 1000 * 1000 * 1000)
    } else {
        (s.as_str(), 1u64)
    };

    let num: u64 = num_str.parse().map_err(|_| format!("Invalid number: {}", num_str))?;
    Ok(num * suffix)
