                ascii_printable: "\x1b[36m".to_string(), // cyan
                ascii_whitespace: "\x1b[32m".to_string(),// green
                ascii_other: "\x1b[32m".to_string(),     // green
                nonascii: "\x1b[33m".to_string(),        // yellow
                offset: "\x1b[90m".to_string(),          // bright black
                reset: "\x1b[39m".to_string(),
            }
        } else {
