    let args = Args::parse();

    if args.print_color_table {
        println!("Color table not implemented yet");
        return Ok(());
    }

    if args.completion.is_some() {
        return Ok(());
    }

    let use_color = match args.color {
        ColorWhen::Always => true,
        ColorWhen::Force => true,
        ColorWhen::Never => false,
        ColorWhen::Auto => atty::is(atty::Stream::Stdout),
    };

    let show_position = !args.plain && !args.no_position;
    let show_characters = !args.plain && !args.no_characters && args.characters == false || args.characters;

    let mut data = Vec::new();
    if let Some(file_path) = &args.file {
        let file = File::open(file_path)?;
        let mut reader = BufReader::new(file);
        reader.read_to_end(&mut data)?;
    } else {
        let stdin = io::stdin();
        let mut reader = stdin.lock();
        reader.read_to_end(&mut data)?;
    }

    // Apply skip
    let skip_bytes = if let Some(skip_str) = args.skip.as_ref() {
        parse_size(skip_str, args.block_size)? as usize
    } else {
        0
    };

    // Apply length
    let take_bytes = if let Some(len_str) = args.length.as_ref() {
        parse_size(len_str, args.block_size)? as usize
    } else {
        data.len()
    };

    let display_offset = parse_size(&args.display_offset, args.block_size)? as i64;

    let start = skip_bytes.min(data.len());
    let end = (start + take_bytes).min(data.len());
    let data = &data[start..end];

    if args.include {
        let filename = args.file.as_ref()
            .and_then(|p| p.file_name())
            .and_then(|n| n.to_str())
            .unwrap_or("data")
            .replace(".", "_")
            .replace("-", "_");

        println!("unsigned char {}[] = {{", filename);
        for (i, chunk) in data.chunks(12).enumerate() {
            if i == 0 {
                print!("  ");
            } else {
                print!(", ");
            }
            for (j, byte) in chunk.iter().enumerate() {
                if j > 0 {
                    print!(", ");
                }
                print!("0x{:02x}", byte);
            }
        }
        println!("\n}};");
        println!("unsigned int {}_len = {};", filename, data.len());
        return Ok(());
    }

    let colors = ColorCodes::new(use_color);
    let group_size = args.group_size.max(1) as usize;

    // Determine layout
    let hex_width = match args.base {
        Base::Hexadecimal => 2,
        Base::Decimal => 3,
        Base::Octal => 3,
        Base::Binary => 8,
    };

    let bytes_per_panel = 8;
    let bytes_per_line = 16;
    let num_panels = 2;

    // Draw top border
    let border_chars = match args.border {
        BorderStyle::Unicode => ("┌", "┬", "┐", "│", "┊", "┼", "├", "┴", "┤", "├", "┴", "┤", "└", "┴", "┘"),
        BorderStyle::Ascii => ("+", "+", "+", "|", "|", "+", "+", "+", "+", "+", "+", "+", "+", "+", "+"),
        BorderStyle::None => ("", "", "", " ", " ", " ", " ", " ", " ", " ", " ", " ", " ", " ", " "),
    };

    if args.border != BorderStyle::None {
        let pos_width = if show_position { 10 } else { 0 };
        let hex_panel_width = if show_characters {
            bytes_per_panel * hex_width + (bytes_per_panel - 1) + 2
        } else {
            bytes_per_panel * hex_width + (bytes_per_panel - 1)
        };
        let char_width = if show_characters { 8 } else { 0 };

        print!("{}", border_chars.0);
        if show_position { print!("{}", "─".repeat(8)); print!("{}", border_chars.1); }
        print!("{}", "─".repeat(hex_panel_width));
        print!("{}", border_chars.1);
        print!("{}", "─".repeat(hex_panel_width));
        if show_characters { 
            print!("{}", border_chars.1);
            print!("{}", "─".repeat(char_width));
            print!("{}", border_chars.1);
            print!("{}", "─".repeat(char_width));
        }
        println!("{}", border_chars.2);
    }

    // Process data in lines
    let mut i = 0;
    let mut last_line: Option<String> = None;
    let mut suppress_until = 0;

    while i < data.len() {
        let line_start = i;
        let line_end = (i + bytes_per_line).min(data.len());
        let line_data = &data[line_start..line_end];

        // Build the hex part
        let mut hex_output = String::new();
        for (j, &byte) in line_data.iter().enumerate() {
            if j > 0 {
                if j == bytes_per_line / 2 {
                    hex_output.push('┊');
                    hex_output.push(' ');
                } else if group_size > 1 && j % group_size == 0 {
                    hex_output.push(' ');
                } else if group_size == 1 && j < line_data.len() {
                    hex_output.push(' ');
                }
            }
            hex_output.push_str(&format!("{}{}{}", colors.for_byte(byte), format_byte(byte, args.base), colors.reset));
        }

        // Build the character part
        let mut char_output = String::new();
        for &byte in line_data.iter() {
            let ch = byte_to_char(byte, args.character_table);
            char_output.push_str(&format!("{}{}{}", colors.for_byte(byte), ch, colors.reset));
        }

        // Pad to full line width
        while line_data.len() < bytes_per_line {
            hex_output.push_str("   ");
            char_output.push(' ');
        }

        // Build full line
        let mut full_line = String::new();
        if show_position {
            let offset = (line_start as i64 + display_offset).max(0) as u64;
            full_line.push_str(&format!("{}{}{:08x}{} ", colors.offset, "│", offset, colors.reset));
        }

        full_line.push_str(&hex_output);
        if show_characters {
            full_line.push_str(&format!(" {}{}{}│{}{}", "│", colors.for_byte(0), "", colors.reset, char_output));
        }

