        if !args.no_squeezing && last_line.is_some() && last_line.as_ref() == Some(&full_line) && i + bytes_per_line < data.len() {
            if suppress_until == 0 {
                println!("{}*{} ", colors.offset, colors.reset);
                suppress_until = i + bytes_per_line;
            }
        } else {
            last_line = Some(full_line.clone());
            suppress_until = 0;
            print!("{}", full_line);
            println!();
        }

        i += bytes_per_line;
    }

    // Draw bottom border
    if args.border != BorderStyle::None {
        let pos_width = if show_position { 10 } else { 0 };
        let hex_panel_width = if show_characters {
            bytes_per_panel * hex_width + (bytes_per_panel - 1) + 2
        } else {
            bytes_per_panel * hex_width + (bytes_per_panel - 1)
        };
        let char_width = if show_characters { 8 } else { 0 };

        print!("{}", border_chars.12);
        if show_position { print!("{}", "─".repeat(8)); print!("{}", border_chars.13); }
        print!("{}", "─".repeat(hex_panel_width));
        print!("{}", border_chars.13);
        print!("{}", "─".repeat(hex_panel_width));
        if show_characters {
            print!("{}", border_chars.13);
            print!("{}", "─".repeat(char_width));
            print!("{}", border_chars.13);
            print!("{}", "─".repeat(char_width));
        }
        println!("{}", border_chars.14);
    }

    Ok(())
}
