}

fn main() -> anyhow::Result<()> {
    let args = Args::parse();

    if args.print_color_table {
        println!("Color table not implemented");
        return Ok(());
    }

    if args.completion.is_some() {
        return Ok(());
    }

    let use_color = match args.color {
        ColorWhen::Always => true,
        ColorWhen::Force => true,
        ColorWhen::Never => false,
        ColorWhen::Auto => atty::is(atty::Stream::Stdout),
    };

    let show_position = !args.plain && !args.no_position;
    let show_characters = if args.plain {
        false
    } else if args.characters {
        true
    } else {
        !args.no_characters
    };

    let mut data = Vec::new();
    if let Some(file_path) = &args.file {
        let file = File::open(file_path)?;
        let mut reader = BufReader::new(file);
        reader.read_to_end(&mut data)?;
    } else {
        let stdin = io::stdin();
        let mut reader = stdin.lock();
        reader.read_to_end(&mut data)?;
    }

    // Apply skip
    let skip_bytes = if let Some(skip_str) = args.skip.as_ref() {
        parse_size(skip_str, args.block_size)? as usize
    } else {
        0
    };

    // Apply length
    let take_bytes = if let Some(len_str) = args.length.as_ref() {
        parse_size(len_str, args.block_size)? as usize
    } else {
        usize::MAX
    };

    let display_offset = parse_size(&args.display_offset, args.block_size)? as i64;

    let start = skip_bytes.min(data.len());
    let end = (start + take_bytes).min(data.len());
    let data = &data[start..end];

    if args.include {
        let filename = args.file.as_ref()
            .and_then(|p| p.file_name())
            .and_then(|n| n.to_str())
            .unwrap_or("data")
            .replace(".", "_")
            .replace("-", "_");

        println!("unsigned char {}[] = {{", filename);
        for (i, chunk) in data.chunks(12).enumerate() {
            if i > 0 { print!(", "); } else { print!("  "); }
            for (j, byte) in chunk.iter().enumerate() {
                if j > 0 { print!(", "); }
                print!("0x{:02x}", byte);
            }
        }
        if !data.is_empty() {
            println!();
        }
        println!("}};");
        println!("unsigned int {}_len = {};", filename, data.len());
        return Ok(());
    }

    let colors = ColorCodes::new(use_color);
    let _group_size = args.group_size.max(1) as usize;
    let border = args.border;

    let bytes_per_line = 16;

    // Draw top border
    if border != BorderStyle::None {
        draw_top_border(border, show_position, show_characters);
    }

    // Process data
    let mut i = 0;
    let mut last_line: Option<Vec<u8>> = None;
    let mut squeeze_shown = false;

    while i < data.len() {
        let line_start = i;
        let line_end = (i + bytes_per_line).min(data.len());
        let line_data = &data[line_start..line_end];

        // Check if this line is identical to the last one
        let should_squeeze = !args.no_squeezing && i + bytes_per_line < data.len() &&
                             last_line.as_deref() == Some(line_data);

        if should_squeeze {
            if !squeeze_shown {
                print_line_separator(&colors, border, show_position);
                squeeze_shown = true;
            }
        } else {
            last_line = Some(line_data.to_vec());
            squeeze_shown = false;

            let offset = (line_start as i64 + display_offset).max(0) as u64;
            print_data_line(&colors, border, show_position, show_characters, 
                          line_data, offset, args.base, args.character_table);
        }

        i = line_end;
    }

    // Draw bottom border
    if border != BorderStyle::None {
        draw_bottom_border(border, show_position, show_characters);
    }

    Ok(())
}

fn draw_top_border(border: BorderStyle, show_position: bool, show_characters: bool) {
    let (tl, tm, tr, _, _, _, _, _, _, _, _, _, _, _, _) = border_chars(border);

    print!("{}", tl);
    if show_position {
        print!("{}{}", "─".repeat(8), tm);
    }
    print!("{}", "─".repeat(25));
    print!("{}", tm);
    print!("{}", "─".repeat(25));
    if show_characters {
        print!("{}", tm);
        print!("{}", "─".repeat(8));
        print!("{}", tm);
        print!("{}", "─".repeat(8));
    }
    println!("{}", tr);
}

fn draw_bottom_border(border: BorderStyle, show_position: bool, show_characters: bool) {
    let (_, _, _, _, _, _, _, _, _, _, _, _, bl, bm, br) = border_chars(border);

    print!("{}", bl);
    if show_position {
        print!("{}{}", "─".repeat(8), bm);
    }
    print!("{}", "─".repeat(25));
    print!("{}", bm);
    print!("{}", "─".repeat(25));
    if show_characters {
        print!("{}", bm);
        print!("{}", "─".repeat(8));
        print!("{}", bm);
        print!("{}", "─".repeat(8));
    }
    println!("{}", br);
}

fn border_chars(border: BorderStyle) -> (&'static str, &'static str, &'static str, &'static str, &'static str, &'static str, &'static str, &'static str, &'static str, &'static str, &'static str, &'static str, &'static str, &'static str, &'static str) {
    match border {
        BorderStyle::Unicode => ("┌", "┬", "┐", "│", "┊", "┼", "├", "┴", "┤", "│", "├", "┴", "└", "┴", "┘"),
        BorderStyle::Ascii => ("+", "+", "+", "|", "|", "+", "+", "+", "+", "|", "+", "+", "+", "+", "+"),
        BorderStyle::None => ("", "", "", " ", " ", " ", " ", " ", " ", " ", "", "", "", "", ""),
    }
}

fn print_line_separator(colors: &ColorCodes, border: BorderStyle, show_position: bool) {
    if border != BorderStyle::None {
        let (_, _, _, _, _, _, ml, _, mr, _, _, _, _, _, _) = border_chars(border);
        if show_position {
            print!("{}", ml);
            print!("{}{}", "─".repeat(8), "─");
        }
    }
    println!("{}*{} ", colors.offset, colors.reset);
}

fn print_data_line(colors: &ColorCodes, border: BorderStyle, show_position: bool, 
                  show_characters: bool, line_data: &[u8], offset: u64, 
                  base: Base, char_table: CharacterTable) {
    let (_, _, _, lv, sep, _, _, _, rv, _, _, _, _, _, _) = border_chars(border);

    if border != BorderStyle::None {
        print!("{}", lv);
    } else {
        print!(" ");
    }

    // Position
    if show_position {
        print!("{}{:08x}{}", colors.offset, offset, colors.reset);
        if border != BorderStyle::None {
            print!("{}", lv);
        } else {
            print!(" ");
        }
    }

    // First hex panel
    for (i, &byte) in line_data.iter().enumerate() {
        if i > 0 {
            if i == 8 {
                print!(" {} ", sep);
            } else {
                print!(" ");
            }
        }
        print!("{}{}{}", colors.for_byte(byte), format_byte(byte, base), colors.reset);
    }

    // Pad first hex panel
    for i in line_data.len()..16 {
        if i > 0 {
            if i == 8 {
                print!(" {} ", sep);
            } else {
                print!(" ");
            }
        }
        print!("  ");
        if base != Base::Hexadecimal {
            print!(" ");
        }
    }

    if show_characters {
        if border != BorderStyle::None {
            print!("{}", lv);
        } else {
            print!(" ");
        }
        for &byte in line_data.iter() {
            let ch = byte_to_char(byte, char_table);
            print!("{}{}{}", colors.for_byte(byte), ch, colors.reset);
        }
        for _ in line_data.len()..16 {
            print!(" ");
        }
    }

    if border != BorderStyle::None {
        print!("{}", rv);
    } else {
        print!(" ");
    }

    println!();
}
