            print!("┬");
            print!("{}", "─".repeat(25));
            if show_characters {
                print!("┬");
                print!("{}", "─".repeat(8));
                print!("┬");
                print!("{}", "─".repeat(8));
            }
            println!("┐");
        }
        BorderStyle::Ascii => {
            print!("+");
            if show_position {
                print!("{}{}", "─".repeat(8), "+");
            }
            print!("{}", "─".repeat(25));
            print!("+");
            print!("{}", "─".repeat(25));
            if show_characters {
                print!("+");
                print!("{}", "─".repeat(8));
                print!("+");
                print!("{}", "─".repeat(8));
            }
            println!("+");
        }
        _ => {}
    }
}

fn draw_bottom_border(border: BorderStyle, show_position: bool, show_characters: bool) {
    match border {
        BorderStyle::Unicode => {
            print!("└");
            if show_position {
                print!("{}{}", "─".repeat(8), "┴");
            }
            print!("{}", "─".repeat(25));
            print!("┴");
            print!("{}", "─".repeat(25));
            if show_characters {
                print!("┴");
                print!("{}", "─".repeat(8));
                print!("┴");
                print!("{}", "─".repeat(8));
            }
            println!("┘");
        }
        BorderStyle::Ascii => {
            print!("+");
            if show_position {
                print!("{}{}", "─".repeat(8), "+");
            }
            print!("{}", "─".repeat(25));
            print!("+");
            print!("{}", "─".repeat(25));
            if show_characters {
                print!("+");
                print!("{}", "─".repeat(8));
                print!("+");
                print!("{}", "─".repeat(8));
            }
            println!("+");
        }
        _ => {}
    }
}

fn print_line_separator(colors: &ColorCodes, border: BorderStyle, show_position: bool) {
    if border != BorderStyle::None {
        if show_position {
            print!("│");
        }
    }
    println!("{}*{} ", colors.offset, colors.reset);
}

fn print_data_line(colors: &ColorCodes, border: BorderStyle, show_position: bool,
                  show_characters: bool, line_data: &[u8], offset: u64,
                  base: Base, char_table: CharacterTable) {
    if border != BorderStyle::None {
        print!("│");
    } else {
        print!(" ");
    }

    if show_position {
        print!("{}{:08x}{}", colors.offset, offset, colors.reset);
        if border != BorderStyle::None {
            print!("│");
        } else {
            print!(" ");
        }
    }

    // First hex panel
    for (i, &byte) in line_data.iter().enumerate() {
        if i > 0 {
            if i == 8 {
                print!(" ┊ ");
            } else {
                print!(" ");
            }
        }
        print!("{}{}{}", colors.for_byte(byte), format_byte(byte, base), colors.reset);
    }

    // Pad first hex panel
    for i in line_data.len()..16 {
        if i > 0 {
            if i == 8 {
                print!(" ┊ ");
            } else {
                print!(" ");
            }
        }
        print!("  ");
        if base != Base::Hexadecimal {
            print!(" ");
        }
    }

    if show_characters {
        if border != BorderStyle::None {
            print!("│");
        } else {
            print!(" ");
        }
        for &byte in line_data.iter() {
            let ch = byte_to_char(byte, char_table);
            print!("{}{}{}", colors.for_byte(byte), ch, colors.reset);
        }
        for _ in line_data.len()..16 {
            print!(" ");
        }
    }

    if border != BorderStyle::None {
        print!("│");
    } else {
        print!(" ");
    }

    println!();
}

fn isatty() -> bool {
    std::env::var("TERM").is_ok()
}
