fn parse_size(s: &str, block_size: u64) -> Result<u64, String> {
    let s = s.to_lowercase();

    if s.ends_with("block") {
        let num_str = s.trim_end_matches("block").trim();
        let num: u64 = num_str.parse().map_err(|_| format!("Invalid"))?;
        return Ok(num * block_size);
    }

    if s.starts_with("0x") {
        return u64::from_str_radix(&s[2..], 16).map_err(|_| format!("Invalid"));
    }

    let (num_str, suffix) = if s.ends_with("kib") {
        (&s[..s.len()-3], 1024u64)
    } else if s.ends_with("mib") {
        (&s[..s.len()-3], 1024 * 1024)
    } else if s.ends_with("gib") {
        (&s[..s.len()-3], 1024 * 1024 * 1024)
    } else if s.ends_with("kb") {
        (&s[..s.len()-2], 1000u64)
    } else if s.ends_with("mb") {
        (&s[..s.len()-2], 1000 * 1000)
    } else if s.ends_with("gb") {
        (&s[..s.len()-2], 1000 * 1000 * 1000)
    } else {
        (s.as_str(), 1u64)
    };

    let num: u64 = num_str.parse().map_err(|_| format!("Invalid"))?;
    Ok(num * suffix)
}

struct ColorCodes {
    null: String,
    ascii_printable: String,
    ascii_whitespace: String,
    nonascii: String,
    offset: String,
    reset: String,
}

impl ColorCodes {
    fn new(use_color: bool) -> Self {
        if use_color {
            ColorCodes {
                null: "\x1b[90m".to_string(),
                ascii_printable: "\x1b[36m".to_string(),
                ascii_whitespace: "\x1b[32m".to_string(),
                nonascii: "\x1b[33m".to_string(),
                offset: "\x1b[90m".to_string(),
                reset: "\x1b[39m".to_string(),
            }
        } else {
            ColorCodes {
                null: "".to_string(),
                ascii_printable: "".to_string(),
                ascii_whitespace: "".to_string(),
                nonascii: "".to_string(),
                offset: "".to_string(),
                reset: "".to_string(),
            }
        }
    }

    fn for_byte(&self, byte: u8) -> &str {
        if byte == 0 {
            &self.null
        } else if byte == b' ' || byte == b'\t' || byte == b'\n' || byte == b'\r' {
            &self.ascii_whitespace
        } else if byte >= 0x20 && byte < 0x7f {
            &self.ascii_printable
        } else {
            &self.nonascii
        }
    }
}

fn byte_to_char(byte: u8, table: CharacterTable) -> char {
    match table {
        CharacterTable::Default => {
            if byte == 0 {
                '⋄'
            } else if byte == b' ' {
                ' '
            } else if byte == b'\t' || byte == b'\n' || byte == b'\r' {
                '_'
            } else if byte >= 0x20 && byte < 0x7f {
                byte as char
            } else if byte < 0x80 {
                '•'
            } else {
                '×'
            }
        }
        CharacterTable::Ascii => {
            if byte >= 0x20 && byte < 0x7f || byte == b' ' {
                byte as char
            } else {
                '.'
            }
        }
    }
}

fn format_byte(byte: u8, base: Base) -> String {
    match base {
        Base::Hexadecimal => format!("{:02x}", byte),
        Base::Decimal => format!("{:03}", byte),
        Base::Octal => format!("{:03o}", byte),
        Base::Binary => format!("{:08b}", byte),
    }
}

fn main() {
    let args = parse_args();

    let use_color = match args.color {
        ColorWhen::Always => true,
        ColorWhen::Force => true,
        ColorWhen::Never => false,
        ColorWhen::Auto => isatty(),
    };

    let show_position = !args.plain && !args.no_position;
    let show_characters = if args.plain {
        false
    } else if args.characters {
        true
    } else {
        !args.no_characters
    };

    let mut data = Vec::new();
    if let Some(file_path) = &args.file {
        if let Ok(file) = File::open(file_path) {
            let mut reader = BufReader::new(file);
            let _ = reader.read_to_end(&mut data);
        }
    } else {
        let stdin = io::stdin();
        let mut reader = stdin.lock();
        let _ = reader.read_to_end(&mut data);
    }

    let skip_bytes = if let Some(skip_str) = args.skip {
        parse_size(&skip_str, args.block_size).unwrap_or(0) as usize
    } else {
        0
    };

    let take_bytes = if let Some(len_str) = args.length {
        parse_size(&len_str, args.block_size).unwrap_or(usize::MAX as u64) as usize
    } else {
        usize::MAX
    };

    let display_offset = parse_size(&args.display_offset, args.block_size).unwrap_or(0) as i64;

    let start = skip_bytes.min(data.len());
    let end = (start + take_bytes).min(data.len());
    let data = &data[start..end];

    if args.include {
        let filename = args.file.as_ref()
            .and_then(|p| p.file_name())
            .and_then(|n| n.to_str())
            .unwrap_or("data")
            .replace(".", "_")
            .replace("-", "_");

        println!("unsigned char {}[] = {{", filename);
        for (i, chunk) in data.chunks(12).enumerate() {
            if i > 0 { print!(", "); } else { print!("  "); }
            for (j, byte) in chunk.iter().enumerate() {
                if j > 0 { print!(", "); }
                print!("0x{:02x}", byte);
            }
        }
        if !data.is_empty() {
            println!();
        }
        println!("}};");
        println!("unsigned int {}_len = {};", filename, data.len());
        return;
    }

    let colors = ColorCodes::new(use_color);
    let border = args.border;
    let bytes_per_line = 16;

    // Draw top border
    if border != BorderStyle::None {
        draw_top_border(border, show_position, show_characters);
    }

    let mut i = 0;
    let mut last_line: Option<Vec<u8>> = None;
    let mut squeeze_shown = false;

    while i < data.len() {
        let line_start = i;
        let line_end = (i + bytes_per_line).min(data.len());
        let line_data = &data[line_start..line_end];

        let should_squeeze = !args.no_squeezing && i + bytes_per_line < data.len() &&
                             last_line.as_deref() == Some(line_data);

        if should_squeeze {
            if !squeeze_shown {
                print_line_separator(&colors, border, show_position);
                squeeze_shown = true;
            }
        } else {
            last_line = Some(line_data.to_vec());
            squeeze_shown = false;

            let offset = (line_start as i64 + display_offset).max(0) as u64;
            print_data_line(&colors, border, show_position, show_characters,
                          line_data, offset, args.base, args.character_table);
        }

        i = line_end;
    }

    // Draw bottom border
    if border != BorderStyle::None {
        draw_bottom_border(border, show_position, show_characters);
    }
}

fn draw_top_border(border: BorderStyle, show_position: bool, show_characters: bool) {
    match border {
        BorderStyle::Unicode => {
            print!("┌");
            if show_position {
                print!("{}{}", "─".repeat(8), "┬");
            }
            print!("{}", "─".repeat(25));
            print!("┬");
            print!("{}", "─".repeat(25));
            if show_characters {
                print!("┬");
                print!("{}", "─".repeat(8));
                print!("┬");
                print!("{}", "─".repeat(8));
            }
            println!("┐");
        }
        BorderStyle::Ascii => {
            print!("+");
            if show_position {
                print!("{}{}", "─".repeat(8), "+");
            }
            print!("{}", "─".repeat(25));
            print!("+");
            print!("{}", "─".repeat(25));
            if show_characters {
                print!("+");
                print!("{}", "─".repeat(8));
                print!("+");
                print!("{}", "─".repeat(8));
            }
            println!("+");
        }
        _ => {}
    }
}

fn draw_bottom_border(border: BorderStyle, show_position: bool, show_characters: bool) {
    match border {
        BorderStyle::Unicode => {
            print!("└");
            if show_position {
                print!("{}{}", "─".repeat(8), "┴");
            }
            print!("{}", "─".repeat(25));
            print!("┴");
            print!("{}", "─".repeat(25));
            if show_characters {
                print!("┴");
                print!("{}", "─".repeat(8));
                print!("┴");
                print!("{}", "─".repeat(8));
            }
            println!("┘");
        }
        BorderStyle::Ascii => {
            print!("+");
            if show_position {
                print!("{}{}", "─".repeat(8), "+");
            }
            print!("{}", "─".repeat(25));
            print!("+");
            print!("{}", "─".repeat(25));
            if show_characters {
                print!("+");
                print!("{}", "─".repeat(8));
                print!("+");
                print!("{}", "─".repeat(8));
            }
            println!("+");
        }
        _ => {}
    }
}

fn print_line_separator(colors: &ColorCodes, border: BorderStyle, show_position: bool) {
    if border != BorderStyle::None {
        if show_position {
            print!("│");
        }
    }
    println!("{}*{} ", colors.offset, colors.reset);
}

fn print_data_line(colors: &ColorCodes, border: BorderStyle, show_position: bool,
                  show_characters: bool, line_data: &[u8], offset: u64,
                  base: Base, char_table: CharacterTable) {
    if border != BorderStyle::None {
        print!("│");
    } else {
        print!(" ");
    }

    if show_position {
        print!("{}{:08x}{}", colors.offset, offset, colors.reset);
        if border != BorderStyle::None {
            print!("│");
        } else {
            print!(" ");
        }
    }

    // First hex panel
    for (i, &byte) in line_data.iter().enumerate() {
        if i > 0 {
            if i == 8 {
                print!(" ┊ ");
            } else {
                print!(" ");
            }
        }
        print!("{}{}{}", colors.for_byte(byte), format_byte(byte, base), colors.reset);
    }

    // Pad first hex panel
    for i in line_data.len()..16 {
        if i > 0 {
            if i == 8 {
                print!(" ┊ ");
            } else {
                print!(" ");
            }
        }
        print!("  ");
        if base != Base::Hexadecimal {
            print!(" ");
        }
    }

    if show_characters {
        if border != BorderStyle::None {
            print!("│");
        } else {
            print!(" ");
        }
        for &byte in line_data.iter() {
            let ch = byte_to_char(byte, char_table);
            print!("{}{}{}", colors.for_byte(byte), ch, colors.reset);
        }
        for _ in line_data.len()..16 {
            print!(" ");
        }
    }

    if border != BorderStyle::None {
        print!("│");
    } else {
        print!(" ");
    }

    println!();
}

fn isatty() -> bool {
    std::env::var("TERM").is_ok()
}
