                print!("{}", "─".repeat(8));
                print!("+");
                print!("{}", "─".repeat(8));
            }
            println!("+");
        }
        _ => {}
    }
}

fn draw_bottom_border(border: BorderStyle, show_position: bool, show_characters: bool) {
