    let take_bytes = if let Some(len_str) = args.length {
        parse_size(&len_str, args.block_size).unwrap_or(usize::MAX as u64) as usize
    } else {
        usize::MAX
    };

    let display_offset = parse_size(&args.display_offset, args.block_size).unwrap_or(0) as i64;

    let start = skip_bytes.min(data.len());
    let end = (start + take_bytes).min(data.len());
    let data = &data[start..end];

    if args.include {
        let filename = args.file.as_ref()
            .and_then(|p| p.file_name())
            .and_then(|n| n.to_str())
            .unwrap_or("data")
            .replace(".", "_")
            .replace("-", "_");

        println!("unsigned char {}[] = {{", filename);
        for (i, chunk) in data.chunks(12).enumerate() {
            if i > 0 { print!(", "); } else { print!("  "); }
            for (j, byte) in chunk.iter().enumerate() {
                if j > 0 { print!(", "); }
                print!("0x{:02x}", byte);
            }
        }
        if !data.is_empty() {
            println!();
        }
        println!("}};");
        println!("unsigned int {}_len = {};", filename, data.len());
        return;
    }

    let colors = ColorCodes::new(use_color);
    let border = args.border;
    let bytes_per_line = 16;

    // Draw top border
    if border != BorderStyle::None {
        draw_top_border(border, show_position, show_characters);
    }

    let mut i = 0;
    let mut last_line: Option<Vec<u8>> = None;
    let mut squeeze_shown = false;

    while i < data.len() {
        let line_start = i;
        let line_end = (i + bytes_per_line).min(data.len());
        let line_data = &data[line_start..line_end];

        let should_squeeze = !args.no_squeezing && i + bytes_per_line < data.len() &&
                             last_line.as_deref() == Some(line_data);

        if should_squeeze {
            if !squeeze_shown {
                print_line_separator(&colors, border, show_position);
                squeeze_shown = true;
            }
        } else {
            last_line = Some(line_data.to_vec());
            squeeze_shown = false;

            let offset = (line_start as i64 + display_offset).max(0) as u64;
            print_data_line(&colors, border, show_position, show_characters,
                          line_data, offset, args.base, args.character_table);
        }

        i = line_end;
    }

    // Draw bottom border
    if border != BorderStyle::None {
        draw_bottom_border(border, show_position, show_characters);
    }
}

fn draw_top_border(border: BorderStyle, show_position: bool, show_characters: bool) {
    match border {
        BorderStyle::Unicode => {
            print!("┌");
            if show_position {
                print!("{}{}", "─".repeat(8), "┬");
            }
            print!("{}", "─".repeat(25));
            print!("┬");
            print!("{}", "─".repeat(25));
            if show_characters {
                print!("┬");
                print!("{}", "─".repeat(8));
                print!("┬");
                print!("{}", "─".repeat(8));
            }
            println!("┐");
        }
        BorderStyle::Ascii => {
            print!("+");
            if show_position {
                print!("{}{}", "─".repeat(8), "+");
            }
            print!("{}", "─".repeat(25));
            print!("+");
            print!("{}", "─".repeat(25));
            if show_characters {
                print!("+");
                print!("{}", "─".repeat(8));
                print!("+");
                print!("{}", "─".repeat(8));
            }
            println!("+");
        }
        _ => {}
    }
}

fn draw_bottom_border(border: BorderStyle, show_position: bool, show_characters: bool) {
    match border {
        BorderStyle::Unicode => {
            print!("└");
            if show_position {
                print!("{}{}", "─".repeat(8), "┴");
            }
            print!("{}", "─".repeat(25));
            print!("┴");
            print!("{}", "─".repeat(25));
            if show_characters {
                print!("┴");
                print!("{}", "─".repeat(8));
