fn parse_size(s: &str, block_size: u64) -> Result<u64, String> {
    let s = s.to_lowercase();

    if s.ends_with("block") {
        let num_str = s.trim_end_matches("block").trim();
        let num: u64 = num_str.parse().map_err(|_| format!("Invalid"))?;
        return Ok(num * block_size);
    }

    if s.starts_with("0x") {
        return u64::from_str_radix(&s[2..], 16).map_err(|_| format!("Invalid"));
    }

    let (num_str, suffix) = if s.ends_with("kib") {
        (&s[..s.len()-3], 1024u64)
    } else if s.ends_with("mib") {
        (&s[..s.len()-3], 1024 * 1024)
    } else if s.ends_with("gib") {
        (&s[..s.len()-3], 1024 * 1024 * 1024)
    } else if s.ends_with("kb") {
        (&s[..s.len()-2], 1000u64)
    } else if s.ends_with("mb") {
        (&s[..s.len()-2], 1000 * 1000)
    } else if s.ends_with("gb") {
        (&s[..s.len()-2], 1000 * 1000 * 1000)
    } else {
        (s.as_str(), 1u64)
    };

    let num: u64 = num_str.parse().map_err(|_| format!("Invalid"))?;
    Ok(num * suffix)
}

struct ColorCodes {
    null: String,
    ascii_printable: String,
    ascii_whitespace: String,
    nonascii: String,
    offset: String,
    reset: String,
}

impl ColorCodes {
    fn new(use_color: bool) -> Self {
        if use_color {
            ColorCodes {
                null: "\x1b[90m".to_string(),
                ascii_printable: "\x1b[36m".to_string(),
                ascii_whitespace: "\x1b[32m".to_string(),
                nonascii: "\x1b[33m".to_string(),
                offset: "\x1b[90m".to_string(),
                reset: "\x1b[39m".to_string(),
            }
        } else {
            ColorCodes {
                null: "".to_string(),
                ascii_printable: "".to_string(),
                ascii_whitespace: "".to_string(),
                nonascii: "".to_string(),
                offset: "".to_string(),
                reset: "".to_string(),
            }
        }
    }

    fn for_byte(&self, byte: u8) -> &str {
        if byte == 0 {
            &self.null
        } else if byte == b' ' || byte == b'\t' || byte == b'\n' || byte == b'\r' {
            &self.ascii_whitespace
        } else if byte >= 0x20 && byte < 0x7f {
            &self.ascii_printable
        } else {
            &self.nonascii
        }
    }
}

fn byte_to_char(byte: u8, table: CharacterTable) -> char {
    match table {
        CharacterTable::Default => {
            if byte == 0 {
                '⋄'
            } else if byte == b' ' {
                ' '
            } else if byte == b'\t' || byte == b'\n' || byte == b'\r' {
                '_'
            } else if byte >= 0x20 && byte < 0x7f {
                byte as char
            } else if byte < 0x80 {
                '•'
            } else {
                '×'
            }
        }
        CharacterTable::Ascii => {
            if (byte >= 0x20 && byte < 0x7f) || byte == b' ' {
                byte as char
            } else {
                '.'
            }
        }
    }
}

fn format_byte(byte: u8, base: Base) -> String {
    match base {
        Base::Hexadecimal => format!("{:02x}", byte),
        Base::Decimal => format!("{:03}", byte),
        Base::Octal => format!("{:03o}", byte),
        Base::Binary => format!("{:08b}", byte),
    }
}

