    plain: bool,
    no_characters: bool,
    characters: bool,
    character_table: CharacterTable,
    no_position: bool,
    display_offset: String,
    base: Base,
    include: bool,
}

fn parse_args() -> Args {
    let mut args = Args {
        file: None,
        length: None,
        skip: None,
        block_size: 512,
        no_squeezing: false,
        color: ColorWhen::Always,
        border: BorderStyle::Unicode,
        plain: false,
        no_characters: false,
        characters: false,
        character_table: CharacterTable::Default,
        no_position: false,
        display_offset: "0".to_string(),
        base: Base::Hexadecimal,
        include: false,
    };

    let env_args: Vec<String> = env::args().collect();
    let mut i = 1;

    while i < env_args.len() {
        let arg = &env_args[i];

        if arg == "--version" || arg == "-V" {
            println!("hexyl 0.16.0");
            std::process::exit(0);
        } else if arg == "--help" || arg == "-h" {
            println!("A command-line hex viewer\n\nUsage: executable [OPTIONS] [FILE]");
            std::process::exit(0);
        } else if arg == "--plain" || arg == "-p" {
            args.plain = true;
            args.no_characters = true;
            args.no_position = true;
            args.border = BorderStyle::None;
            args.color = ColorWhen::Never;
        } else if arg == "--no-squeezing" || arg == "-v" {
            args.no_squeezing = true;
        } else if arg == "--no-characters" {
            args.no_characters = true;
        } else if arg == "-C" || arg == "--characters" {
            args.characters = true;
        } else if arg == "-P" || arg == "--no-position" {
            args.no_position = true;
        } else if arg == "-i" || arg == "--include" {
            args.include = true;
        } else if arg == "-n" || arg == "--length" || arg == "-c" || arg == "-l" {
            if i + 1 < env_args.len() {
                i += 1;
                args.length = Some(env_args[i].clone());
            }
        } else if arg.starts_with("--length=") {
            args.length = Some(arg[9..].to_string());
        } else if arg == "-s" || arg == "--skip" {
            if i + 1 < env_args.len() {
                i += 1;
                args.skip = Some(env_args[i].clone());
            }
        } else if arg.starts_with("--skip=") {
            args.skip = Some(arg[7..].to_string());
        } else if arg == "--color" {
            if i + 1 < env_args.len() {
                i += 1;
                args.color = match env_args[i].as_str() {
                    "always" => ColorWhen::Always,
                    "auto" => ColorWhen::Auto,
                    "never" => ColorWhen::Never,
                    "force" => ColorWhen::Force,
                    _ => ColorWhen::Always,
                };
            }
        } else if arg.starts_with("--color=") {
            args.color = match &arg[8..] {
                "always" => ColorWhen::Always,
                "auto" => ColorWhen::Auto,
                "never" => ColorWhen::Never,
                "force" => ColorWhen::Force,
                _ => ColorWhen::Always,
            };
        } else if arg == "--border" {
            if i + 1 < env_args.len() {
                i += 1;
                args.border = match env_args[i].as_str() {
                    "unicode" => BorderStyle::Unicode,
                    "ascii" => BorderStyle::Ascii,
                    "none" => BorderStyle::None,
                    _ => BorderStyle::Unicode,
                };
            }
        } else if arg.starts_with("--border=") {
            args.border = match &arg[9..] {
                "unicode" => BorderStyle::Unicode,
                "ascii" => BorderStyle::Ascii,
                "none" => BorderStyle::None,
                _ => BorderStyle::Unicode,
            };
        } else if arg == "-o" || arg == "--display-offset" {
            if i + 1 < env_args.len() {
                i += 1;
                args.display_offset = env_args[i].clone();
            }
        } else if arg.starts_with("--display-offset=") {
            args.display_offset = arg[17..].to_string();
        } else if arg == "-b" || arg == "--base" {
            if i + 1 < env_args.len() {
                i += 1;
                args.base = match env_args[i].as_str() {
                    "binary" => Base::Binary,
                    "octal" => Base::Octal,
                    "decimal" => Base::Decimal,
                    "hexadecimal" => Base::Hexadecimal,
                    _ => Base::Hexadecimal,
                };
            }
        } else if arg.starts_with("--base=") {
            args.base = match &arg[7..] {
                "binary" => Base::Binary,
                "octal" => Base::Octal,
                "decimal" => Base::Decimal,
                "hexadecimal" => Base::Hexadecimal,
                _ => Base::Hexadecimal,
            };
        } else if arg == "--character-table" {
            if i + 1 < env_args.len() {
                i += 1;
                args.character_table = match env_args[i].as_str() {
                    "ascii" => CharacterTable::Ascii,
                    _ => CharacterTable::Default,
                };
            }
        } else if arg.starts_with("--character-table=") {
            args.character_table = match &arg[18..] {
                "ascii" => CharacterTable::Ascii,
                _ => CharacterTable::Default,
            };
        } else if !arg.starts_with("-") {
            args.file = Some(PathBuf::from(arg));
        }

        i += 1;
    }

    args
}

