enum CharacterTable { Default, Ascii }

fn main() {
    let args = parse_args();

    let use_color = match args.color {
        ColorWhen::Always => true,
        ColorWhen::Force => true,
        ColorWhen::Never => false,
        ColorWhen::Auto => isatty(),
    };

    let show_position = !args.plain && !args.no_position;
    let show_characters = if args.plain { false } else if args.characters { true } else { !args.no_characters };

    let mut data = Vec::new();
    if let Some(file_path) = &args.file {
        if let Ok(file) = File::open(file_path) {
            let mut reader = BufReader::new(file);
            let _ = reader.read_to_end(&mut data);
        }
    } else {
        let stdin = io::stdin();
        let mut reader = stdin.lock();
        let _ = reader.read_to_end(&mut data);
    }

    let skip_bytes = if let Some(skip_str) = args.skip {
        parse_size(&skip_str, args.block_size).unwrap_or(0) as usize
    } else { 0 };

    let take_bytes = if let Some(len_str) = args.length {
        parse_size(&len_str, args.block_size).unwrap_or(usize::MAX as u64) as usize
    } else { usize::MAX };

    let display_offset = parse_size(&args.display_offset, args.block_size).unwrap_or(0) as i64;

    let start = skip_bytes.min(data.len());
    let end = (start + take_bytes).min(data.len());
    let data = &data[start..end];

    if args.include {
        let filename = args.file.as_ref()
            .and_then(|p| p.file_name())
            .and_then(|n| n.to_str())
            .unwrap_or("data")
            .replace(".", "_")
            .replace("-", "_");

        println!("unsigned char {}[] = {{", filename);
        for (i, chunk) in data.chunks(12).enumerate() {
            if i > 0 { print!(", "); } else { print!("  "); }
            for (j, byte) in chunk.iter().enumerate() {
                if j > 0 { print!(", "); }
                print!("0x{:02x}", byte);
            }
        }
        if !data.is_empty() { println!(); }
        println!("}};");
        println!("unsigned int {}_len = {};", filename, data.len());
        return;
    }

    let border = args.border;

    if border != BorderStyle::None {
        print_border_top(border, show_position, show_characters);
    }

    let mut i = 0;
    let mut last_line: Option<Vec<u8>> = None;
    let mut squeeze_shown = false;

    while i < data.len() {
        let line_start = i;
        let line_end = (i + 16).min(data.len());
        let line_data = &data[line_start..line_end];

        let should_squeeze = !args.no_squeezing && i + 16 < data.len() &&
                             last_line.as_deref() == Some(line_data);

        if should_squeeze {
            if !squeeze_shown {
                print_line_squeeze(use_color, border, show_position);
                squeeze_shown = true;
            }
        } else {
            last_line = Some(line_data.to_vec());
            squeeze_shown = false;

            let offset = (line_start as i64 + display_offset).max(0) as u64;
            print_line(use_color, border, show_position, show_characters, line_data, offset, args.base, args.character_table);
        }

        i = line_end;
    }

    if border != BorderStyle::None {
        print_border_bottom(border, show_position, show_characters);
    }
}

fn print_line(use_color: bool, border: BorderStyle, show_position: bool, show_characters: bool, 
              line_data: &[u8], offset: u64, base: Base, char_table: CharacterTable) {
    if border != BorderStyle::None {
        print!("│");
    } else {
        print!(" ");
    }

    if show_position {
        let color_offset = if use_color { "\x1b[90m" } else { "" };
        let color_reset = if use_color { "\x1b[39m" } else { "" };
        print!("{}{:08x}{}", color_offset, offset, color_reset);
        if border != BorderStyle::None {
            print!("│");
        } else {
            print!(" ");
        }
    }

    print!(" ");

    // Hex part
    for (i, &byte) in line_data.iter().enumerate() {
        if i > 0 {
            if i == 8 {
                if border != BorderStyle::None {
                    print!(" ┊ ");
                } else {
                    print!("   ");
                }
            } else {
                print!(" ");
            }
        }
        let color = get_color(byte, use_color);
        let reset = if use_color { "\x1b[39m" } else { "" };
        print!("{}{}{}", color, format_byte(byte, base), reset);
    }

    // Pad hex part
    for i in line_data.len()..16 {
        if i > 0 {
            if i == 8 {
                if border != BorderStyle::None {
                    print!(" ┊ ");
                } else {
                    print!("   ");
                }
            } else {
                print!(" ");
            }
        }
        print!("  ");
        if base != Base::Hexadecimal {
            print!(" ");
        }
    }

    print!(" ");

    // Character part
    if show_characters {
        if border != BorderStyle::None {
            print!("│");
        } else {
            print!(" ");
        }

        for (i, &byte) in line_data.iter().enumerate() {
            if i == 8 && line_data.len() > 8 && border != BorderStyle::None {
                print!("┊");
            }
            let color = get_color(byte, use_color);
            let reset = if use_color { "\x1b[39m" } else { "" };
            let ch = byte_to_char(byte, char_table);
            print!("{}{}{}", color, ch, reset);
        }

        for i in line_data.len()..16 {
            if i == 8 && border != BorderStyle::None {
                print!("┊");
            }
            print!(" ");
        }
    }

    if border != BorderStyle::None {
        print!("│");
    } else {
        print!(" ");
    }

    println!();
}

fn print_line_squeeze(use_color: bool, border: BorderStyle, show_position: bool) {
    let color_offset = if use_color { "\x1b[90m" } else { "" };
    let color_reset = if use_color { "\x1b[39m" } else { "" };
    if border != BorderStyle::None {
        if show_position {
            print!("│");
        }
    }
    println!("{}*{} ", color_offset, color_reset);
}

fn print_border_top(border: BorderStyle, show_position: bool, show_characters: bool) {
    match border {
        BorderStyle::Unicode => {
            print!("┌");
            if show_position {
                print!("{}┬", "─".repeat(8));
            }
            print!("{}┬{}", "─".repeat(25), "─".repeat(25));
            if show_characters {
                print!("┬{}┬{}", "─".repeat(8), "─".repeat(8));
            }
            println!("┐");
        }
        BorderStyle::Ascii => {
            print!("+");
            if show_position {
                print!("{}+", "─".repeat(8));
            }
            print!("{}+{}", "─".repeat(25), "─".repeat(25));
            if show_characters {
                print!("+{}+{}", "─".repeat(8), "─".repeat(8));
            }
            println!("+");
        }
        _ => {}
    }
}

fn print_border_bottom(border: BorderStyle, show_position: bool, show_characters: bool) {
    match border {
        BorderStyle::Unicode => {
            print!("└");
            if show_position {
                print!("{}┴", "─".repeat(8));
            }
            print!("{}┴{}", "─".repeat(25), "─".repeat(25));
            if show_characters {
                print!("┴{}┴{}", "─".repeat(8), "─".repeat(8));
            }
            println!("┘");
        }
        BorderStyle::Ascii => {
            print!("+");
            if show_position {
                print!("{}+", "─".repeat(8));
            }
            print!("{}+{}", "─".repeat(25), "─".repeat(25));
            if show_characters {
                print!("+{}+{}", "─".repeat(8), "─".repeat(8));
            }
            println!("+");
        }
        _ => {}
    }
}

fn get_color(byte: u8, use_color: bool) -> &'static str {
    if !use_color { return ""; }
    if byte == 0 {
        "\x1b[90m"
    } else if byte == b' ' || byte == b'\t' || byte == b'\n' || byte == b'\r' {
        "\x1b[32m"
    } else if byte >= 0x20 && byte < 0x7f {
        "\x1b[36m"
    } else {
        "\x1b[33m"
    }
}

fn byte_to_char(byte: u8, table: CharacterTable) -> char {
    match table {
        CharacterTable::Default => {
            if byte == 0 { '⋄' }
            else if byte == b' ' { ' ' }
            else if byte == b'\t' || byte == b'\n' || byte == b'\r' { '_' }
            else if byte >= 0x20 && byte < 0x7f { byte as char }
            else if byte < 0x80 { '•' }
            else { '×' }
        }
        CharacterTable::Ascii => {
            if (byte >= 0x20 && byte < 0x7f) || byte == b' ' { byte as char } else { '.' }
        }
    }
}

fn format_byte(byte: u8, base: Base) -> String {
    match base {
        Base::Hexadecimal => format!("{:02x}", byte),
        Base::Decimal => format!("{:03}", byte),
        Base::Octal => format!("{:03o}", byte),
        Base::Binary => format!("{:08b}", byte),
    }
}

fn parse_size(s: &str, block_size: u64) -> Result<u64, String> {
    let s = s.to_lowercase();

    if s.ends_with("block") {
        let num_str = s.trim_end_matches("block").trim();
        let num: u64 = num_str.parse().map_err(|_| format!("Invalid"))?;
        return Ok(num * block_size);
    }

    if s.starts_with("0x") {
        return u64::from_str_radix(&s[2..], 16).map_err(|_| format!("Invalid"));
    }

    let (num_str, suffix) = if s.ends_with("kib") {
        (&s[..s.len()-3], 1024u64)
    } else if s.ends_with("mib") {
        (&s[..s.len()-3], 1024 * 1024)
    } else if s.ends_with("gib") {
        (&s[..s.len()-3], 1024 * 1024 * 1024)
    } else if s.ends_with("kb") {
        (&s[..s.len()-2], 1000u64)
    } else if s.ends_with("mb") {
        (&s[..s.len()-2], 1000 * 1000)
    } else if s.ends_with("gb") {
        (&s[..s.len()-2], 1000 * 1000 * 1000)
    } else {
        (s.as_str(), 1u64)
    };

    let num: u64 = num_str.parse().map_err(|_| format!("Invalid"))?;
    Ok(num * suffix)
}

struct Args {
    file: Option<PathBuf>,
    length: Option<String>,
    skip: Option<String>,
    block_size: u64,
    no_squeezing: bool,
    color: ColorWhen,
    border: BorderStyle,
    plain: bool,
    no_characters: bool,
    characters: bool,
    character_table: CharacterTable,
    no_position: bool,
    display_offset: String,
    base: Base,
    include: bool,
}

fn parse_args() -> Args {
    let mut args = Args {
        file: None,
        length: None,
        skip: None,
        block_size: 512,
        no_squeezing: false,
        color: ColorWhen::Always,
        border: BorderStyle::Unicode,
        plain: false,
        no_characters: false,
        characters: false,
        character_table: CharacterTable::Default,
        no_position: false,
        display_offset: "0".to_string(),
        base: Base::Hexadecimal,
        include: false,
    };

    let env_args: Vec<String> = env::args().collect();
    let mut i = 1;

    while i < env_args.len() {
        let arg = &env_args[i];

        if arg == "--version" || arg == "-V" {
            println!("hexyl 0.16.0");
            std::process::exit(0);
        } else if arg == "--help" || arg == "-h" {
            println!("A command-line hex viewer\n\nUsage: executable [OPTIONS] [FILE]");
            std::process::exit(0);
        } else if arg == "--plain" || arg == "-p" {
            args.plain = true;
            args.no_characters = true;
            args.no_position = true;
            args.border = BorderStyle::None;
            args.color = ColorWhen::Never;
        } else if arg == "--no-squeezing" || arg == "-v" {
            args.no_squeezing = true;
        } else if arg == "--no-characters" {
            args.no_characters = true;
        } else if arg == "-C" || arg == "--characters" {
            args.characters = true;
        } else if arg == "-P" || arg == "--no-position" {
            args.no_position = true;
        } else if arg == "-i" || arg == "--include" {
            args.include = true;
        } else if arg == "-n" || arg == "--length" || arg == "-c" || arg == "-l" {
            if i + 1 < env_args.len() {
                i += 1;
                args.length = Some(env_args[i].clone());
            }
        } else if arg.starts_with("--length=") {
            args.length = Some(arg[9..].to_string());
        } else if arg == "-s" || arg == "--skip" {
            if i + 1 < env_args.len() {
                i += 1;
                args.skip = Some(env_args[i].clone());
            }
        } else if arg.starts_with("--skip=") {
            args.skip = Some(arg[7..].to_string());
        } else if arg == "--color" {
            if i + 1 < env_args.len() {
                i += 1;
                args.color = match env_args[i].as_str() {
                    "always" => ColorWhen::Always,
                    "auto" => ColorWhen::Auto,
                    "never" => ColorWhen::Never,
                    "force" => ColorWhen::Force,
                    _ => ColorWhen::Always,
                };
            }
        } else if arg.starts_with("--color=") {
            args.color = match &arg[8..] {
                "always" => ColorWhen::Always,
                "auto" => ColorWhen::Auto,
                "never" => ColorWhen::Never,
                "force" => ColorWhen::Force,
                _ => ColorWhen::Always,
            };
        } else if arg == "--border" {
            if i + 1 < env_args.len() {
                i += 1;
                args.border = match env_args[i].as_str() {
                    "unicode" => BorderStyle::Unicode,
                    "ascii" => BorderStyle::Ascii,
                    "none" => BorderStyle::None,
                    _ => BorderStyle::Unicode,
                };
            }
        } else if arg.starts_with("--border=") {
            args.border = match &arg[9..] {
                "unicode" => BorderStyle::Unicode,
                "ascii" => BorderStyle::Ascii,
                "none" => BorderStyle::None,
                _ => BorderStyle::Unicode,
            };
        } else if arg == "-o" || arg == "--display-offset" {
            if i + 1 < env_args.len() {
                i += 1;
                args.display_offset = env_args[i].clone();
            }
        } else if arg.starts_with("--display-offset=") {
            args.display_offset = arg[17..].to_string();
        } else if arg == "-b" || arg == "--base" {
            if i + 1 < env_args.len() {
                i += 1;
                args.base = match env_args[i].as_str() {
                    "binary" => Base::Binary,
                    "octal" => Base::Octal,
                    "decimal" => Base::Decimal,
                    "hexadecimal" => Base::Hexadecimal,
                    _ => Base::Hexadecimal,
                };
            }
        } else if arg.starts_with("--base=") {
            args.base = match &arg[7..] {
                "binary" => Base::Binary,
                "octal" => Base::Octal,
                "decimal" => Base::Decimal,
                "hexadecimal" => Base::Hexadecimal,
                _ => Base::Hexadecimal,
            };
        } else if arg == "--character-table" {
            if i + 1 < env_args.len() {
                i += 1;
                args.character_table = match env_args[i].as_str() {
                    "ascii" => CharacterTable::Ascii,
                    _ => CharacterTable::Default,
                };
            }
        } else if arg.starts_with("--character-table=") {
            args.character_table = match &arg[18..] {
                "ascii" => CharacterTable::Ascii,
                _ => CharacterTable::Default,
            };
        } else if !arg.starts_with("-") {
            args.file = Some(PathBuf::from(arg));
        }

        i += 1;
    }

    args
}

fn isatty() -> bool {
    std::env::var("TERM").is_ok()
}
